function drawRuinTiles(ctx: CanvasRenderingContext2D) {
  // 1. [0, 384] ruin-flagstone: Ancient temple ashlar paving slabs
  const drawFlagstone = (ox: number, oy: number, mossy: boolean) => {
    ctx.fillStyle = "#8a877d";
    ctx.fillRect(ox, oy, 128, 128);
    const slabs = [
      [2, 2, 60, 60, "#979489"], [66, 2, 60, 60, "#858278"],
      [2, 66, 60, 60, "#838076"], [66, 66, 60, 60, "#939085"],
    ] as const;
    for (const [x, y, w, h, color] of slabs) {
      ctx.fillStyle = color;
      ctx.fillRect(ox + x, oy + y, w, h);
      ctx.fillStyle = "rgba(255,255,255,0.16)";
      ctx.fillRect(ox + x, oy + y, w, 4);
      ctx.fillRect(ox + x, oy + y, 4, h);
      ctx.fillStyle = "rgba(30,28,24,0.22)";
      ctx.fillRect(ox + x, oy + y + h - 4, w, 4);
      ctx.fillRect(ox + x + w - 4, oy + y, 4, h);
    }
    ctx.strokeStyle = "#535048";
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.moveTo(ox, oy + 64); ctx.lineTo(ox + 128, oy + 64);
    ctx.moveTo(ox + 64, oy); ctx.lineTo(ox + 64, oy + 128);
    ctx.stroke();
    ctx.strokeStyle = "#625e56";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(ox + 18, oy + 14); ctx.lineTo(ox + 38, oy + 32); ctx.lineTo(ox + 33, oy + 52);
    ctx.moveTo(ox + 84, oy + 78); ctx.lineTo(ox + 106, oy + 96);
    ctx.stroke();
    if (mossy) {
      ctx.fillStyle = "#567546";
      const mossPatches = [
        [0, 56, 36, 16], [56, 0, 16, 42], [48, 52, 32, 24],
        [88, 56, 40, 16], [56, 84, 18, 44], [10, 10, 18, 14], [94, 92, 22, 18],
      ];
      for (const [mx, my, mw, mh] of mossPatches) {
        ctx.beginPath();
        ctx.roundRect(ox + mx, oy + my, mw, mh, 6);
        ctx.fill();
      }
      ctx.fillStyle = "#6c8f58";
      ctx.fillRect(ox + 54, oy + 56, 20, 14);
      ctx.fillRect(ox + 6, oy + 58, 18, 10);
    }
  };

  drawFlagstone(0, 384, false);
  drawFlagstone(128, 384, true);

  // 3. [256, 384] ruin-altar-rune: Boss Seal Altar & Arcane Rune Stone
  {
    const ox = 256, oy = 384;
    ctx.fillStyle = "#484a52";
    ctx.fillRect(ox, oy, 128, 128);
    ctx.strokeStyle = "#2f3138";
    ctx.lineWidth = 6;
    ctx.strokeRect(ox + 3, oy + 3, 122, 122);
    ctx.strokeStyle = "#7a7468";
    ctx.lineWidth = 2;
    ctx.strokeRect(ox + 10, oy + 10, 108, 108);
    // Glowing golden-cyan Boss Seal circles & octagon
    ctx.strokeStyle = "#d9af52";
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.arc(ox + 64, oy + 64, 44, 0, Math.PI * 2);
    ctx.stroke();
    ctx.strokeStyle = "#66d4e6";
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.arc(ox + 64, oy + 64, 30, 0, Math.PI * 2);
    ctx.moveTo(ox + 64, oy + 12); ctx.lineTo(ox + 64, oy + 116);
    ctx.moveTo(ox + 12, oy + 64); ctx.lineTo(ox + 116, oy + 64);
    ctx.moveTo(ox + 28, oy + 28); ctx.lineTo(ox + 100, oy + 100);
    ctx.moveTo(ox + 100, oy + 28); ctx.lineTo(ox + 28, oy + 100);
    ctx.stroke();
    ctx.fillStyle = "#f2c968";
    ctx.beginPath();
    ctx.arc(ox + 64, oy + 64, 11, 0, Math.PI * 2);
    ctx.fill();
  }

  // 4. [384, 384] ruin-wall-block: Heavy Ashlar Stone Masonry Wall & Top
  {
    const ox = 384, oy = 384;
    ctx.fillStyle = "#6e6b62";
    ctx.fillRect(ox, oy, 128, 128);
    const rows = [0, 32, 64, 96];
    rows.forEach((ry, rIdx) => {
      const shift = (rIdx % 2) * 32;
      for (let bx = -shift; bx < 128; bx += 64) {
        const x0 = Math.max(0, bx + 2), x1 = Math.min(128, bx + 62);
        if (x1 <= x0) continue;
        ctx.fillStyle = (rIdx + bx) % 3 === 0 ? "#7d7a70" : "#67645c";
        ctx.fillRect(ox + x0, oy + ry + 2, x1 - x0, 28);
        ctx.fillStyle = "rgba(255,255,255,0.15)";
        ctx.fillRect(ox + x0, oy + ry + 2, x1 - x0, 3);
        ctx.fillStyle = "rgba(20,18,15,0.28)";
        ctx.fillRect(ox + x0, oy + ry + 27, x1 - x0, 3);
      }
    });
    ctx.fillStyle = "#527042";
    ctx.fillRect(ox + 8, oy + 96, 36, 12);
    ctx.fillRect(ox + 78, oy + 64, 28, 10);
  }

  // 5. [0, 512] ruin-pillar: Tall Fluted Temple Column (bottom-aligned)
  {
    const ox = 0, oy = 512;
    // Plinth base
    ctx.fillStyle = "#5c5951";
    ctx.fillRect(ox + 26, oy + 110, 76, 18);
    ctx.fillStyle = "#8a867c";
    ctx.fillRect(ox + 30, oy + 102, 68, 12);
    // Column shaft
    ctx.fillStyle = "#9c988d";
    ctx.fillRect(ox + 38, oy + 24, 52, 80);
    // Fluting & shading
    for (let fx = 42; fx <= 84; fx += 8) {
      ctx.fillStyle = fx < 64 ? "#b5b1a5" : "#78756c";
      ctx.fillRect(ox + fx, oy + 26, 4, 76);
    }
    // Capital
    ctx.fillStyle = "#8f8b80";
    ctx.fillRect(ox + 30, oy + 14, 68, 12);
    ctx.fillStyle = "#a8a498";
    ctx.fillRect(ox + 24, oy + 6, 72, 10);
    // Cracks & moss
    ctx.strokeStyle = "#45423c";
    ctx.lineWidth = 3;
    ctx.strokeRect(ox + 38, oy + 24, 52, 80);
    ctx.beginPath();
    ctx.moveTo(ox + 38, oy + 56); ctx.lineTo(ox + 90, oy + 62);
    ctx.stroke();
    ctx.fillStyle = "#587848";
    ctx.fillRect(ox + 30, oy + 98, 26, 14);
    ctx.fillRect(ox + 68, oy + 106, 28, 12);
  }

  // 6. [128, 512] ruin-broken-pillar: Shattered Half-Column (bottom-aligned)
  {
    const ox = 128, oy = 512;
    ctx.fillStyle = "#5c5951";
    ctx.fillRect(ox + 26, oy + 110, 76, 18);
    ctx.fillStyle = "#8a867c";
    ctx.fillRect(ox + 30, oy + 100, 68, 12);
    // Broken jagged shaft
    ctx.fillStyle = "#969287";
    ctx.beginPath();
    ctx.moveTo(ox + 36, oy + 102);
    ctx.lineTo(ox + 36, oy + 48);
    ctx.lineTo(ox + 52, oy + 36);
    ctx.lineTo(ox + 68, oy + 52);
    ctx.lineTo(ox + 92, oy + 40);
    ctx.lineTo(ox + 92, oy + 102);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = "#45423c";
    ctx.lineWidth = 3;
    ctx.stroke();
    for (let fx = 42; fx <= 84; fx += 9) {
      ctx.fillStyle = fx < 64 ? "#b0aca0" : "#757268";
      ctx.fillRect(ox + fx, oy + 54, 4, 46);
    }
    ctx.fillStyle = "#587848";
    ctx.fillRect(ox + 34, oy + 94, 32, 18);
  }

  // 7. [256, 512] ruin-fallen-column: Collapsed Column Drum & Rubble (bottom-aligned)
  {
    const ox = 256, oy = 512;
    ctx.fillStyle = "#7d796f";
    ctx.beginPath();
    ctx.roundRect(ox + 12, oy + 76, 104, 44, 10);
    ctx.fill();
    ctx.strokeStyle = "#45423c";
    ctx.lineWidth = 3;
    ctx.stroke();
    ctx.fillStyle = "#9e9a8e";
    ctx.beginPath();
    ctx.ellipse(ox + 24, oy + 98, 12, 20, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = "#628250";
    ctx.beginPath();
    ctx.roundRect(ox + 34, oy + 74, 48, 18, 6);
    ctx.fill();
  }

  // 8. [384, 512] ruin-stele: Ancient Boss Seal Obelisk / Stele (bottom-aligned)
  {
    const ox = 384, oy = 512;
    ctx.fillStyle = "#42444c";
    ctx.fillRect(ox + 26, oy + 110, 76, 18);
    ctx.fillStyle = "#545761";
    ctx.beginPath();
    ctx.moveTo(ox + 34, oy + 110);
    ctx.lineTo(ox + 42, oy + 22);
    ctx.lineTo(ox + 64, oy + 6);
    ctx.lineTo(ox + 86, oy + 22);
    ctx.lineTo(ox + 94, oy + 110);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = "#2b2d33";
    ctx.lineWidth = 3;
    ctx.stroke();
    // Glowing runes on the stele
    ctx.strokeStyle = "#66d4e6";
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.arc(ox + 64, oy + 46, 12, 0, Math.PI * 2);
    ctx.moveTo(ox + 64, oy + 24); ctx.lineTo(ox + 64, oy + 96);
    ctx.moveTo(ox + 52, oy + 72); ctx.lineTo(ox + 76, oy + 72);
    ctx.stroke();
    ctx.fillStyle = "#f2c968";
    ctx.beginPath();
    ctx.arc(ox + 64, oy + 46, 5, 0, Math.PI * 2);
    ctx.fill();
  }
}

async function buildCoastTileset(map: TileMap): Promise<Tileset> {
  const width = ATLAS_COLS * TILE_SIZE;
  const height = ATLAS_ROWS * TILE_SIZE;
  const existing = map.tilesets.find(item => item.id === AK_COAST_TILESET_ID);
  if (existing && existing.height === height) return existing;
  let png = new Blob([FALLBACK_PNG], { type: "image/png" });
  if (typeof document !== "undefined") {
    try {
      const sources = new Map<string, CanvasImageSource>();
      for (const tex of map.world?.textures ?? []) {
        sources.set(tex.id, await tilesetImage(tex.png));
      }
      const canvas = document.createElement("canvas");
      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext("2d");
      if (ctx) {
        for (const spec of COAST_SPRITES) {
          const image = sources.get(spec.sourceTexture);
          if (!image) continue;
          const [rx, ry, rw, rh] = spec.region;
          ctx.drawImage(image, rx, ry, rw, rh, spec.slot[0], spec.slot[1], TILE_SIZE, TILE_SIZE);
        }
        drawRuinTiles(ctx);
        const generated = await new Promise<Blob | null>(resolve =>
          typeof canvas.toBlob === "function" ? canvas.toBlob(resolve, "image/png") : resolve(null),
        );
        if (generated) png = generated;
      }
    } catch {
      // Keep fallback PNG in headless test environments.
    }
  }
  return { id: AK_COAST_TILESET_ID, name: "AK 海岸与遗迹.png", tileSize: TILE_SIZE, width, height, png };
}

export async function applyAkBeachDesign(map: TileMap): Promise<TileMap> {
  const world = map.world;
  if (world?.id !== "ak-world-v1" || map.width !== 200 || map.height !== 160) return map;
  const coastTileset = await buildCoastTileset(map);
  const tilesets = map.tilesets.some(item => item.id === AK_COAST_TILESET_ID)
    ? map.tilesets.map(item => item.id === AK_COAST_TILESET_ID ? coastTileset : item)
    : [...map.tilesets, coastTileset];
  const paletteMap = new Map(map.palettes.map(item => [item.id, item]));
  for (const palette of AK_COAST_PALETTES) {
    paletteMap.set(palette.id, palette);
  }
  const palettes = Array.from(paletteMap.values());

  const alreadyV4 = world.previewVersion === AK_PREVIEW_VERSION
    && map.layers.some(layer => layer.id === AK_COAST_LAYER_ID)
    && Boolean(world.elevations?.[86 * 200 + 114]);
  if (alreadyV4) {
    return { ...map, tilesets, palettes };
  }

  const layers: Layer[] = map.layers.map(layer => {
    if (layer.id === "ak-ground") {
      const cells: Record<number, Cell> = { ...layer.cells };
      for (const index of BEACH_GRASS_TILES) {
        const cur = cells[index];
        if (!cur || ("palette" in cur && cur.palette === "sand")) {
          cells[index] = { palette: "grass" };
        }
      }
      for (const index of BEACH_ROCK_TILES) {
        const cur = cells[index];
        if (!cur || ("palette" in cur && cur.palette === "sand")) {
          cells[index] = { palette: "rock" };
        }
      }
      for (const index of DESERT_SAND_FIX_TILES) {
        const cur = cells[index];
        if (!cur || ("palette" in cur && cur.palette === "rock")) {
          cells[index] = { palette: "sand" };
        }
      }
      for (const [paletteId, indices] of Object.entries(RUIN_GROUND_GROUPS)) {
        for (const index of indices) {
          cells[index] = { palette: paletteId };
        }
      }
      return { ...layer, cells };
    }
    if (layer.id === "ak-roads") {
      const cells: Record<number, Cell> = { ...layer.cells };
      for (const index of BEACH_ROAD_TILES) {
        if (!cells[index]) cells[index] = { palette: "road" };
      }
      return { ...layer, cells };
    }
    return layer;
  }).filter(layer => layer.id !== AK_COAST_LAYER_ID);

  const existingDeco = map.layers.find(layer => layer.id === AK_COAST_LAYER_ID)?.cells ?? {};
  const decoCells: Record<number, Cell> = { ...existingDeco };
  for (const [paletteId, indices] of Object.entries(BEACH_DECORATION_GROUPS)) {
    for (const index of indices) {
      if (!decoCells[index]) decoCells[index] = { palette: paletteId };
    }
  }
  layers.push({
    id: AK_COAST_LAYER_ID,
    name: "海岸与遗迹",
    visible: true,
    cells: decoCells,
  });

  const elevations: Record<number, number> = { ...(world.elevations ?? {}) };
  for (const [key, metres] of Object.entries(RUIN_ELEVATIONS)) {
    elevations[Number(key)] = metres;
  }

  const cards = world.cards?.filter(card => !card.id || !CLEARED_ISLAND_CARD_IDS.has(card.id));

  return {
    ...map,
    tilesets,
    palettes,
    layers,
    world: { ...world, cards, elevations, previewVersion: AK_PREVIEW_VERSION },
  };
}
